 'use strict';
let questPromptSeen=false,questOfferQueued=false;
function maybeAdvancementQuest(){if(player.level<30||player.job!=='swordsman'||player.promotionTokens>0||questPromptSeen||questOfferQueued||player.questState==='accepted')return;if(screen!=='play'||paused||run?.finished||!$('modal').hidden||!$('characterOverlay').hidden||tradeOverlay)return;player.questState='offered';questOfferQueued=true;setTimeout(()=>{questOfferQueued=false;if(screen==='play'&&!paused&&!run?.finished&&$('modal').hidden&&$('characterOverlay').hidden){questPromptSeen=true;showAdvancementQuest()}},150)}
function showAdvancementQuest(){if(player.level<30||player.job!=='swordsman')return;if(player.promotionTokens)return openPromotionChoices();questPromptSeen=true;modal('เควสต์เปลี่ยนอาชีพ · Lv.30','โค่นราชาสไลม์ในบททดสอบนักรบเพื่อรับตรานักรบพิเศษ เมื่อชนะให้เปิดกระเป๋าหมวดใช้งานและกดตราเพื่อเลือกหนึ่งในสามสาย',[['รับเควสต์และเข้าท้าทาย',()=>{player.questState='accepted';save();closeModal();beginStage(4)},true]]);$('modal').querySelector('.dialog-card').classList.add('quest-card')}
function promotionTokenIcon(){return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="m24 3 17 8v17L24 45 7 28V11Z" fill="#beab67" stroke="#ffe59c" stroke-width="3"/><path d="m27 10-13 19 5 3 15-19Z" fill="#f3ebc6"/><path d="m12 26 13 9M19 30l-5 8" stroke="#54684c" stroke-width="3"/></svg>'}
function openPromotionChoices(){if(!canPromote())return;const body=document.createElement('div');body.className='promotion-options';let chosen=null;for(const branch of BRANCHES){const b=document.createElement('button');b.className='promotion-choice';b.dataset.job=branch.id;const title=document.createElement('strong');title.textContent=JOBS[branch.id].name;const desc=document.createElement('small');desc.textContent=branch.summary+' · '+Object.keys(SECOND_SKILLS[branch.id]).length+' สกิล';b.append(title,desc);b.onclick=()=>{chosen=branch.id;body.querySelectorAll('.promotion-choice').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});$('confirmPromotionBtn').disabled=false};body.append(b)}modal('ตรานักรบ · เลือกอาชีพขั้น 2',body,[['ยืนยันเปลี่ยนอาชีพ',()=>{if(!chosen)return;const job=chosen;closeModal();if(promoteCharacter(job)){if(!$('characterOverlay').hidden)renderCharacterWindow();updateUI();toast('เปลี่ยนเป็น '+JOBS[job].name+' แล้ว · ได้รับ SP ขั้น 2')}} ,true]]);const confirm=$('modalButtons').querySelector('button');confirm.id='confirmPromotionBtn';confirm.disabled=true}
